// src/lead/phone.ts
var PHONE_COUNTRY_CODE = "+998";
var PHONE_DIGITS = 9;
function normalizePhoneDigits(input) {
  let digits = input.replace(/\D/g, "");
  if (digits.length > PHONE_DIGITS && digits.startsWith("998")) digits = digits.slice(3);
  return digits.slice(0, PHONE_DIGITS);
}
function isValidPhone(digits) {
  return new RegExp(`^\\d{${PHONE_DIGITS}}$`).test(digits);
}
function phoneE164(digits) {
  return `${PHONE_COUNTRY_CODE}${normalizePhoneDigits(digits)}`;
}

// src/lead/contact.ts
var NAME_MAX = 50;
var NAME_RE = /^[\p{Script=Latin}\p{Script=Cyrillic}][\p{Script=Latin}\p{Script=Cyrillic}ʼʻ'‘’\- ]*$/u;
function nameError(value, required) {
  const v = value.trim();
  if (!v) return required ? "required" : void 0;
  if (v.length > NAME_MAX || !NAME_RE.test(v)) return "invalid";
  return void 0;
}
function validateContact(c) {
  const errors = {};
  const first = nameError(c.firstName, true);
  if (first) errors.firstName = first;
  const last = nameError(c.lastName ?? "", false);
  if (last) errors.lastName = last;
  if (!c.phone) errors.phone = "required";
  else if (!isValidPhone(c.phone)) errors.phone = "invalid";
  if (c.consent !== true) errors.consent = "required";
  return errors;
}
function cleanContact(c) {
  const clean = (s) => (s ?? "").trim().replace(/\s+/g, " ");
  return {
    firstName: clean(c.firstName),
    lastName: clean(c.lastName),
    phone: c.phone,
    consent: c.consent
  };
}

